  "Electricity emission factor, if actual values are used": "実績値を使用する場合の電力排出係数",
  "Electricity from different sources, in which quantities — and the supplier's name and country where another installation supplies it": "異なる供給源からの電力、その数量。別の設備が供給している場合は供給者の名称と国",
  "Electricity imported into the Union": "連合へ輸入された電力",
  "Electricity per source": "供給源ごとの電力",
  "Electricity per source: quantity, country, emission factor": "供給源ごとの電力：数量、国、排出係数",
  "Electricity produced inside the installation": "設備内で生産された電力",
  "Electricity produced inside the installation: co-generation or separate generation, fossil or renewable, and whether it is exported from a production process (a–d)": "設備内で生産された電力：コジェネレーションまたは個別発電、化石燃料または再生可能エネルギー、および生産工程から輸出されるかどうか（a〜d）",
  "Electricity used in each production process": "各生産工程で使用された電力",
  "Emissions determined by other methods": "他の方法で算定された排出量",
