  "Goods, by CN code and functional unit": "CN コードおよび機能単位別の品目",
  "How the attributed direct and indirect emissions of each production process were calculated": "各生産工程の配分済み直接排出量と間接排出量の算出方法",
  "If relevant, a list of the non-CBAM goods produced per production process and the quantity produced": "該当する場合、生産工程ごとの CBAM 対象外品目の一覧と生産量",
  "Indirect emissions (goods not in Annex II)": "間接排出量（附属書II 外の品目）",
  "Indirect emissions of the installation": "設備の間接排出量",
  "Indirect emissions: share on actual and on default values; specific indirect emissions": "間接排出量：実績値とデフォルト値の割合、固有の間接排出量",
