  "List of all goods produced, in the functional unit, for each CN code": "CN コードごとの、機能単位で表した生産品目の一覧",
  "Measurable heat imported from or exported to other installations, and which": "他の設備から輸入または他の設備へ輸出された測定可能な熱、およびその設備",
  "Measurable heat imported or exported": "輸入または輸出された測定可能な熱",
  "Months of monitoring, for a new installation": "新規設備のモニタリング期間（月数）",
  "Non-CBAM goods produced per production process": "生産工程ごとの CBAM 対象外品目の生産量",
  "Non-CBAM production processes": "CBAM 対象外の生産工程",
  "Operator and installation of origin of each precursor": "各前駆体の原産地の事業者と設備",
  "Operator and installation of origin of each precursor on an actual value": "実績値を用いる各前駆体の原産地の事業者と設備",
