  "Precursors of one type from several installations": "複数の設備から入手した、1 種類の前駆体",
  "Precursors on actual values: CN code, name, country, period, specific embedded emissions": "実績値を用いる前駆体：CN コード、名称、国、期間、固有の埋込排出量",
  "Precursors on actual values: CN code, name, country, reporting period, specific embedded emissions": "実績値を用いる前駆体：CN コード、名称、国、報告期間、固有の埋込排出量",
  "Precursors on an actual value from outside the Union": "連合外からの実績値を用いる前駆体",
  "Precursors on default values: CN code, name, country of origin, default value": "デフォルト値を用いる前駆体：CN コード、名称、原産国、デフォルト値",
