  "Precursors received from different reporting periods": "異なる報告期間に受け入れた前駆体",
  "Quality assurance of the information technology systems": "情報技術システムの品質保証",
  "Quality assurance of the measurement equipment: calibrated, adjusted and checked at regular intervals, against traceable standards": "測定機器の品質保証：トレーサブルな標準に対して、定期的に校正、調整、点検されていること",
  "Quantity of each precursor produced at the installation and used by it, and in each production process": "設備内で生産され、設備内で使用された各前駆体の数量、および各生産工程での数量",
