  "The alloying elements of what was made this month, from the mill test certificates, weighted by the heats cast.": "当月製造分の合金元素。ミルシート（鋼材試験証明書）から、鋳造チャージで加重平均したものです。",
  "The report states Mn, Cr, Ni and the other alloying elements for the year: the months' figures, weighted by what was made in each. Leave a month empty if it was ordinary carbon steel with only trace elements.": "報告書には、年間の Mn、Cr、Ni などの合金元素を記載します。各月の数値は、その月の製造量で加重します。微量元素のみを含む一般炭素鋼だった月は、空欄のままにしてください。",
