  "What goes to the verifier": "検証機関に提出する内容",
  "Everything this installation hands over for {year}, in one package: the reports you write, and the papers that travel with them.": "この設備が {year} 年分として1つのパッケージで提出するすべての内容：作成したレポートと、それに添付される書類。",
  "Attachments": "添付書類",
  "Not reports you write. Each is an index of papers that travel in the package, beside the reports — and neither holds the package back.": "作成するレポートではありません。それぞれは、レポートと並んでパッケージに含まれる書類の索引です。いずれもパッケージの提出を妨げるものではありません。",
  "Monitoring plan, operator's emissions report, summary report": "モニタリング計画、事業者の排出量報告書、サマリー報告書",
  "Addendum": "補足資料",
  "Electricity goes to the EU — one per declarant": "電力をEUに送る場合 — 申告者ごとに1つ",
  "Not needed — no electricity goes to the EU": "不要 — EUに送られる電力はありません",
  "Precursor verification reports, supporting evidence": "前駆物質の検証報告書、裏付けとなる証跡",
  "Contains": "含む",
  "to get": "取得",
  "Still to get": "未取得",
  "Each installation you report on hands over one package a year: the monitoring plan, the operator's emissions report and the summary report — a declarant addendum where electricity goes to the EU — and, beside them, the verification reports of your precursors' installations and the supporting evidence. It covers every product the site makes, and downloads once all of it is complete.": "報告対象の設備ごとに、年1つのパッケージを提出します。内容はモニタリング計画、事業者の排出量報告書、サマリー報告書、電力をEUに送る場合の申告者向け補足資料、そしてそれらと並ぶ前駆物質の設備の検証報告書と裏付け証跡です。拠点で製造するすべての製品を対象とし、すべてが完了するとダウンロードできるようになります。",
