  "Supporting evidence and records": "裏付けとなる証跡と記録",
  "What the installation monitors and how, element by element as the template lists them. The verifier reads it before the year is verified.": "設備がモニタリングする内容と方法を、テンプレートの項目ごとに記載したものです。検証機関は年度の検証前にこれを確認します。",
  "The full report the verifier verifies. It is in English (Article 10(4)).": "検証機関が検証する完全な報告書です。英語で作成されます（第10条(4)）。",
  "The shortened report passed on to authorised CBAM declarants (Article 8).": "認定CBAM申告者に提供される簡略版の報告書（第8条）。",
  "One per authorised declarant, only for electricity imported into the EU.": "認定申告者ごとに1つ。EUに輸入される電力についてのみ作成します。",
  "This installation does not export electricity to the EU, so no addendum is needed.": "この設備はEUへ電力を輸出していないため、補足資料は不要です。",
  "The verification reports of the installations that made your precursors on actual values. The reports themselves are in the package, beside this index.": "実測値を用いて貴社の前駆物質を製造した設備の検証報告書です。報告書本体はこの索引と並んでパッケージに含まれます。",
  "Every document behind a figure, and the figure it supports, so the verifier can sample a month and find its paper. The documents themselves are in the package, beside this index.": "数値の裏付けとなるすべての書類と、それが裏付ける数値。検証機関が任意の月を抽出し、その書類を確認できるようにするものです。書類本体はこの索引と並んでパッケージに含まれます。",
