  "Compare the values with the document, then tap here. Unticked files are not filed.": "数値を書類と照合してから、ここを押してください。チェックを外したファイルは登録されません。",
  "This file can be ticked once every question is answered.": "すべての質問に回答すると、このファイルにチェックを入れられます。",
