  "Everything you dropped has been filed or set aside.": "ドロップしたすべての書類が登録または保留されました。",
  "Not filled unless you tick it below — check it against the document.": "以下でチェックを入れない限り入力されません。書類と照合してください。",
  "Confirm {docs} documents · fill {values} values": "{docs} 件の書類を確認 · {values} 件の数値を入力",
  "Confirm {docs} documents": "{docs} 件の書類を確認",
  "Guessed from the file name — check what it is.": "ファイル名から推定されました。書類の種類を確認してください。",
  "{n} documents waiting for your check": "確認待ちの書類 {n} 件",
