  "AI filled {n} values from your documents — they are in blue.": "AI が書類から {n} 件の数値を入力しました。青色で表示されています。",
  "AI can make mistakes — check each value against its document. Typing over a value makes it yours.": "AI は誤る場合があります。各数値を書類と照合してください。数値を上書きすると、その数値は貴社の入力値になります。",
  "AI can make mistakes, even on rows marked ready. Check each value against its document before you confirm.": "準備完了と表示された行でも、AI は誤る場合があります。確認する前に、各数値を書類と照合してください。",
  "AI can make mistakes. You check every value before anything is saved.": "AI は誤る場合があります。保存される前に、すべての数値を確認してください。",
  "Also filled:": "その他に入力された項目：",
  "Have the documents already?": "書類はすでにお手元にありますか？",
  "Add documents and let Certrace fill the form": "書類を追加して、Certrace にフォームを入力させる",
  "Drop this month's bills, fuel invoices and ERP exports. AI reads each one, files it and fills the matching figures. You check everything before it is saved — AI can make mistakes.": "今月の請求書、燃料インボイス、ERP エクスポートをドロップしてください。AI が各書類を読み取り、登録し、該当する数値を入力します。保存前にすべて確認してください。AI は誤る場合があります。",
  "Add documents & auto-fill": "書類を追加して自動入力",
  "AI reads your bills and invoices and fills the form. You check before saving — AI can make mistakes.": "AI が請求書とインボイスを読み取り、フォームに入力します。保存前に確認してください。AI は誤る場合があります。",
