  "Electricity bill for March 2026 — 412,800 kWh on meter SMP-7781204.": "2026年3月の電気料金請求書 — メーター SMP-7781204 で 412,800 kWh。",
  "Scanned electricity bill for April 2026. Several digits are smudged; the total kWh is partly obscured and a handwritten note repeats it with a question mark.": "2026年4月の電気料金請求書（スキャン）。数字の一部がかすれています。合計 kWh は一部が不明瞭で、手書きのメモに疑問符付きで同じ値が記載されています。",
  "Natural gas invoice for March 2026 — 185,400 Sm³ delivered at RY-DP-014.": "2026年3月の天然ガス請求書 — RY-DP-014 で 185,400 Sm³ を受入。",
  "Delivery note for 12,000 litres of diesel B7 on 18 April 2026. No price on the note.": "2026年4月18日付、軽油 B7 12,000 リットルの納品書。納品書に価格の記載はありません。",
  "ERP production summary for March 2026 — 8,420.5 t of hot-rolled coil.": "2026年3月の ERP 生産サマリー — 熱間圧延コイル 8,420.5 t。",
  "Calibration certificate for gas flow meter GFM-22-0391, calibrated 12 January 2026, next due 12 January 2027.": "ガス流量計 GFM-22-0391 の校正証明書。2026年1月12日校正、次回校正期限は2027年1月12日。",
  "EN 10204 3.1 certificate for 250 t of SS400 slab, heat H26-03117, delivered March 2026.": "SS400 スラブ 250 t（チャージ H26-03117）の EN 10204 3.1 証明書。2026年3月納入。",
