  "Good afternoon, {name}.": "{name} 様、こんにちは。",
  "Your CBAM Q2 cycle is open and the deadline is inside three weeks. Here's what needs you.": "CBAM 第2四半期のサイクルが開始されており、締切まで3週間以内です。対応が必要な項目は以下のとおりです。",
