  "{count} CBAM-critical suppliers are overdue on {declaration}.": "{declaration} で、CBAM 重要サプライヤー {count} 社が期限超過です。",
  "Late = rejected. Send a reminder, or escalate, before the package locks.": "期限後の提出は受理されません。パッケージがロックされる前にリマインダーを送信するか、エスカレーションしてください。",
  "Latest activity": "最新のアクティビティ",
