  "Reporting cycles.": "報告サイクル。",
  "Every regulation, market and period you're filing for. A declaration is the unit of compliance — scope it once, the platform runs the rest.": "申告対象となるすべての規制、市場、期間。申告はコンプライアンスの単位です。一度範囲を設定すれば、残りはプラットフォームが処理します。",
