  "Clear the filters, or start a new declaration — CBAM compliance or a custom buyer request.": "フィルターを解除するか、新しい申告を開始してください（CBAM コンプライアンスまたはカスタム購入者依頼）。",
  "Scope it once.": "範囲は一度だけ設定。",
