  "Saved as draft": "下書きとして保存しました",
  "Pick up where you left off from the Declarations list.": "申告一覧から中断した箇所を再開してください。",
  "Declaration created.": "申告を作成しました。",
  "{name} — {suppliers} suppliers · {products} products · {lots} lots queued.": "{name} — サプライヤー {suppliers} 社 · 製品 {products} 件 · ロット {lots} 件が待機中。",
  "Compliance regulation": "コンプライアンス規制",
  "Which regime are you reporting for? Certrace launched on CBAM — the obligation that bites first for exporters into the EU. The rest run on the same engine and switch on as their data models are verified.": "どの制度について報告しますか？ Certrace は CBAM から提供を開始しました。EU に輸出する事業者にとって最初に適用される義務です。その他の制度も同じエンジンで動作し、データモデルの検証が完了次第、順次有効になります。",
  "Export route": "輸出ルート",
  "Where do you export from, and into which market? {reg} applies to goods entering the EU — your origin sets the emission-factor library Certrace calculates with.": "どこから、どの市場へ輸出しますか？ {reg} は EU に輸入される品目に適用されます。原産地によって、Certrace が計算に用いる排出係数ライブラリが決まります。",
  "From — country of origin": "出発地 — 原産国",
  "To — destination market": "仕向地 — 仕向市場",
  "Enforces {reg}": "{reg} を適用",
  "No {reg} obligation here": "ここでは {reg} の義務はありません",
  "factors from": "係数の出典",
