  "United States": "米国",
  "Coming soon · electronics, steel, textiles.": "近日対応予定 · 電子機器、鉄鋼、繊維。",
  "Coming soon · aluminium, palm oil (EUDR).": "近日対応予定 · アルミニウム、パーム油（EUDR）。",
  "Planned · rubber, palm oil, electronics.": "計画中 · ゴム、パーム油、電子機器。",
  "EU CBAM Registry · via importer / declarant": "EU CBAM レジストリ · 輸入者 / 申告者経由",
  "What is this declaration for?": "この申告の目的は何ですか？",
  "Choose one — the official CBAM filing, or a specific buyer's data request. Each has its own qualification checklist, so keep the two separate.": "いずれかを選択してください — 正式な CBAM 届出、または特定の購入者によるデータ依頼です。それぞれ独自の適格性チェックリストがあるため、両者は分けて管理してください。",
  "CBAM Compliance": "CBAM コンプライアンス",
  "Automatically prepares supplier data collection based on CBAM requirements. Fields, CN codes and templates are generated for you.": "CBAM の要件に基づき、サプライヤーからのデータ収集を自動で準備します。項目、CN コード、テンプレートは自動生成されます。",
  "Buyer Request": "購入者からの依頼",
  "Create a custom supplier request for buyer-specific information — documents, certificates and questionnaires on top of the carbon data.": "購入者固有の情報を求めるカスタムのサプライヤー依頼を作成します。炭素データに加えて、書類、証明書、質問票を依頼できます。",
  "e.g. CBAM 2026 Annual": "例：CBAM 2026 年次",
  "e.g. ABC Buyer Carbon Data Request": "例：ABC 購入者 炭素データ依頼",
  "Request name": "依頼名",
  "Shown to suppliers and on every reminder. Make it recognisable.": "サプライヤーとすべてのリマインダーに表示されます。わかりやすい名称にしてください。",
  "Request description (optional)": "依頼の説明（任意）",
  "Context for your suppliers — what this is for.": "サプライヤー向けの背景情報 — この依頼の目的。",
  "e.g. Annual CBAM carbon data for our EU steel exports. Please report at installation level.": "例：EU向け鉄鋼輸出に関する年次 CBAM 炭素データ。設備単位で報告してください。",
  "EU buyer / importer (required)": "EU 購入者 / 輸入者（必須）",
  "EU buyer / importer": "EU 購入者 / 輸入者",
  "Who imports these goods into the EU? Their Authorised CBAM Declarant files the declaration — Certrace addresses the Communication Template and the O3CI share to them.": "これらの品目を EU に輸入するのは誰ですか？ その認定 CBAM 申告者が申告を提出します。Certrace は通知テンプレートと O3CI 共有を、その申告者宛てに送付します。",
  "The buyer this data request is for.": "このデータ依頼の対象となる購入者。",
  "Buyer legal name": "購入者の正式名称",
  "EORI number": "EORI 番号",
  "Format: 2-letter country + 6–15 characters, e.g. DE551234567890": "形式：2文字の国コード + 6〜15 文字（例：DE551234567890）",
  "The declarant's Registry identifier.": "申告者のレジストリ識別子。",
  "Contact email": "連絡先メール",
  "Enter a valid email address.": "有効なメールアドレスを入力してください。",
  "Where the Communication Template is sent.": "通知テンプレートの送付先。",
  "Buyer requests can run on any cadence. Pick the rhythm that matches how this buyer wants the data.": "購入者からの依頼は任意の頻度で実施できます。この購入者がデータを求める頻度に合わせて選択してください。",
  "Official CBAM declarations are annual — but you can collect supplier data quarterly if that fits your cycle.": "正式な CBAM 申告は年次ですが、貴社のサイクルに合う場合は四半期ごとにサプライヤーデータを収集できます。",
  "Quarterly": "四半期",
  "Semi-annual": "半期",
  "Official CBAM cadence — recommended. Suppliers can report at year-end.": "正式な CBAM の頻度 — 推奨。サプライヤーは年末に報告できます。",
  "Collect supplier data each quarter (one quarter at a time).": "四半期ごとにサプライヤーデータを収集（1四半期ずつ）。",
  "Once per calendar year.": "暦年に1回。",
  "One half-year at a time.": "1半期ずつ。",
