  "Search the CBAM goods catalogue by product name, CN code or HS code. Pick everything in scope — reorder to match how you brief suppliers.": "製品名、CN コード、HS コードで CBAM 品目カタログを検索します。対象となるものをすべて選択し、サプライヤーへの説明順に合わせて並べ替えてください。",
  "Search… e.g. Hot-rolled coil, 7208, or aluminium": "検索… 例：熱延コイル、7208、アルミニウム",
  "All goods": "すべての品目",
  "Iron & Steel": "鉄鋼",
  "{count} in catalogue": "カタログ掲載 {count} 件",
  "No products match “{query}”.": "「{query}」に一致する製品はありません。",
  "In scope": "対象",
  "Nothing selected yet. Tick products on the left to add them.": "まだ選択されていません。左側の製品にチェックを入れて追加してください。",
  "Move up": "上へ移動",
  "Move down": "下へ移動",
  "Classification & report fields": "分類とレポート項目",
  "Certrace classified each product automatically — category, CN / HS codes and the CBAM template come from the catalogue and can't be edited. The checklist below reflects the data points that actually apply to the goods you selected.": "Certrace が各製品を自動で分類しました。カテゴリ、CN / HS コード、CBAM テンプレートはカタログから取得され、編集できません。以下のチェックリストは、選択した品目に実際に適用されるデータ項目を示しています。",
  "CBAM report fields": "CBAM レポート項目",
  "Carbon data to request": "依頼する炭素データ",
  "{included} of {total} included": "{total} 件中 {included} 件を含む",
  "These are the data points CBAM requires for the goods you selected. Required fields are locked on; the rest are recommended and on by default — keep or drop them to match how you collect data.": "これらは、選択した品目について CBAM が求めるデータ項目です。必須項目は常にオンになっています。その他は推奨項目で、既定でオンになっています。貴社のデータ収集方法に合わせて、残すか削除してください。",
  "Choose the carbon-data fields this buyer needs. Recommended fields are pre-selected because buyers commonly ask for them — adjust freely, keeping at least one.": "この購入者が必要とする炭素データ項目を選択してください。推奨項目は、購入者が一般的に求めるため事前に選択されています。自由に調整できますが、少なくとも1つは残してください。",
  "Select {field}": "{field} を選択",
  "Deselect {field}": "{field} の選択を解除",
  "Embedded emissions": "埋め込み排出量",
  "Verification": "検証",
  "Installation name": "設備名",
  "Legal name of the producing installation": "生産設備の正式名称",
  "Installation country": "設備の所在国",
  "Site address": "拠点住所",
  "Full street address of the production site": "生産拠点の完全な住所",
  "UN location code of the site, e.g. THRYG": "拠点の UN ロケーションコード（例：THRYG）",
  "Geographic coordinates": "地理座標",
  "Latitude / longitude of the main emission source": "主要排出源の緯度 / 経度",
  "Aggregated goods category": "集計品目カテゴリ",
  "CBAM aggregated category for the CN code": "CN コードに対応する CBAM 集計カテゴリ",
  "8-digit Combined Nomenclature code": "8桁の統合関税率表（CN）コード",
  "Production process / route": "生産工程 / ルート",
  "Steel: e.g. BF-BOF, EAF, DRI-EAF · Aluminium: e.g. electrolysis (Hall-Héroult), remelt, extrusion": "鉄鋼：例 BF-BOF、EAF、DRI-EAF · アルミニウム：例 電解（ホール・エルー法）、再溶解、押出",
  "Quantity covered by this request (net mass, t)": "この依頼が対象とする数量（正味質量、t）",
  "Net mass the exporter bought from you in the period — not your installation's total production": "期間中に輸出者が貴社から購入した正味質量。設備の総生産量ではありません",
  "Direct specific emissions — own process (tCO₂e/t)": "直接固有排出量 — 自工程（tCO₂e/t）",
  "Direct emissions of YOUR production step only — precursors are added separately below": "貴社の生産工程のみの直接排出量。前駆物質分は下記で別途加算されます",
  "Indirect specific emissions — own process (tCO₂e/t)": "間接固有排出量 — 自工程（tCO₂e/t）",
  "Electricity-related emissions of YOUR production step only": "貴社の生産工程のみの電力関連排出量",
  "Total embedded emissions (tCO₂e/t)": "埋め込み排出量の合計（tCO₂e/t）",
  "Derived automatically: own direct + own indirect + precursor contribution": "自動算出：自工程の直接排出 + 自工程の間接排出 + 前駆物質の寄与",
  "Determination method (actual / default)": "算定方法（実測 / デフォルト）",
  "Whether actual data or default values were used": "実測データとデフォルト値のどちらを使用したか",
  "Electricity consumed (MWh/t)": "電力消費量（MWh/t）",
  "Electricity used per tonne of output — drives indirect emissions": "生産量1トンあたりの電力使用量。間接排出量を左右します",
  "Electricity emission factor & source": "電力排出係数と出典",
  "Grid / PPA factor and its documented source": "系統 / PPA 係数とその文書化された出典",
  "Electrolysis technology (prebake / Søderberg)": "電解技術（プリベーク / セーデルベリ）",
  "Smelting route — only for primary (unwrought) aluminium from electrolysis": "製錬ルート — 電解による一次（未加工）アルミニウムのみ",
  "Relevant precursors & their embedded emissions": "関連する前駆物質と埋め込み排出量",
  "One row per input material: quantity consumed per tonne of this good × its embedded emissions": "投入材ごとに1行：この品目1トンあたりの消費量 × 埋め込み排出量",
  "Precursor production routes": "前駆物質の製造ルート",
  "How each precursor was produced, where known": "判明している場合、各前駆物質の製造方法",
  "Carbon price due in country of origin": "原産国で課される炭素価格",
  "Carbon price actually paid per tonne of CO₂e, if any": "実際に支払った CO₂e 1トンあたりの炭素価格（支払いがある場合）",
  "Carbon price currency": "炭素価格の通貨",
  "Currency the carbon price was paid in (THB or EUR)": "炭素価格を支払った通貨（THB または EUR）",
  "Form of carbon price (ETS / tax / levy)": "炭素価格の形態（ETS / 税 / 賦課金）",
  "Instrument under which the price was paid": "価格を支払った制度",
  "Verification & verifier details": "検証と検証機関の詳細",
  "Accredited verifier and verification outcome": "認定検証機関と検証結果",
  "Suppliers, lots & quantities": "サプライヤー、ロット、数量",
  "Map suppliers to each product, then add the production lots you bought in this period. Each lot keeps its own quantity and optional production period, so the embedded-emissions calculation stays fully traceable.": "サプライヤーを各製品に紐づけ、この期間に調達した製造ロットを追加してください。各ロットは独自の数量と任意の製造期間を保持するため、埋め込み排出量の計算を完全に追跡できます。",
  "We produce this ourselves": "自社で生産しています",
  "No Smart Link is sent for {org} — you'll fill this product's data in the portal under your own org profile. Everything after that is identical: AI check, calculation, audit trail.": "{org} 向けの Smart Link は送信されません。この製品のデータは、貴社の組織プロフィールからポータルに入力してください。その後の処理（AI チェック、計算、監査証跡）はすべて同じです。",
  "this is us": "自社",
