  "Deadline & reminders": "締切とリマインダー",
  "Set the submission deadline suppliers see, and let Certrace chase them automatically so you don't have to.": "サプライヤーに表示される提出期限を設定し、Certrace による自動催促を有効にしてください。手作業での催促は不要です。",
  "Submission deadline": "提出期限",
  "The date suppliers must submit by.": "サプライヤーが提出しなければならない期限日。",
  "The date suppliers must submit by — defaulted to one month after the period ends ({end}).": "サプライヤーが提出しなければならない期限日です。既定では期間終了（{end}）の1か月後に設定されています。",
  "The reporting period runs until {end} — suppliers can only report complete data after it ends. Pick a later deadline.": "報告期間は {end} まで続きます。サプライヤーは期間終了後にのみ完全なデータを報告できます。より後の期限を選択してください。",
