  "Every site you operate yourself. Register them here once and their monthly data lands in your inbox instead of going out to a supplier. Your plan covers one site.": "貴社が自ら運営するすべての拠点。ここに一度登録すれば、その月次データはサプライヤーに送られる代わりに貴社の受信トレイに届きます。貴社のプランは 1 拠点までが対象です。",
  "Every site you operate yourself. Register them here once and their monthly data lands in your inbox instead of going out to a supplier. Your plan covers {cap} sites.": "貴社が自ら運営するすべての拠点。ここに一度登録すれば、その月次データはサプライヤーに送られる代わりに貴社の受信トレイに届きます。貴社のプランは {cap} 拠点までが対象です。",
  "CN {code} would be a new code on your plan.": "CN {code} はプランにおける新規コードになります。",
  "Codes you already report — and any number of sites or years reporting them — cost nothing more.": "すでに報告している コード、およびそれを報告する拠点や年度の数は、追加料金なしです。",
  "{year} would be a new reporting year. Archiving a finished year frees its slot — nothing behind it is deleted.": "{year} は新しい報告年度になります。完了した年度をアーカイブすると枠が空きます。アーカイブしてもデータは削除されません。",
