  "Once suppliers submit and you approve their figures, the cost, the hotspots and the benchmark all appear here — across every declaration at once.": "サプライヤーが提出し、貴社が数値を承認すると、コスト、ホットスポット、ベンチマークがすべての申告にわたってここに表示されます。",
