  "Priced at": "適用単価",
  "{amount} on every tonne you ship. An estimate for planning: the declarant buys at the published auction average for the week of import.": "出荷する 1 トンごとに {amount}。計画用の概算です。申告者は輸入週に公表されたオークション平均価格で購入します。",
  "Certificate price in EUR per tonne CO2e": "CO2e 1トンあたりの証書価格（EUR）",
  "Carbon hotspots": "炭素のホットスポット",
  "Ranked by absolute chargeable emissions across every declaration in scope — the same mill appearing on four filings counts once, as one relationship.": "対象となるすべての申告にわたる課金対象排出量の絶対値で順位付けしています。4 件の届出に登場する同じ工場は、1 つの取引先として 1 回だけ計上されます。",
  "by supplier": "サプライヤー別",
  "by product": "製品別",
  "{count} of {total} suppliers": "サプライヤー {total} 社中 {count} 社",
  "carry {pct}% of your chargeable emissions — about {amount} in certificates. That's the shortlist for a conversation about actual data, a cleaner route, or a different supplier.": "貴社の課金対象排出量の {pct}% を占め、証書コストは約 {amount} です。実データ、よりクリーンなルート、または別のサプライヤーについて話し合う際の候補リストです。",
  "Data that needs refreshing": "更新が必要なデータ",
  "Supplier records age. A figure past a year, or one reported for a period you're no longer filing, has to be re-confirmed before it goes into another declaration.": "サプライヤーの記録は時間とともに古くなります。1 年を超えた数値、または貴社がもう申告していない期間について報告された数値は、別の申告に使用する前に再確認が必要です。",
  "No supplier records yet — they build up as suppliers submit, and each one makes the next request shorter.": "サプライヤーの記録はまだありません。サプライヤーが提出するにつれて蓄積され、記録が増えるほど次回以降の依頼は短くなります。",
  "Your one supplier record is current.": "サプライヤーの記録 1 件は最新です。",
  "All {count} supplier records are current.": "サプライヤーの記録 {count} 件はすべて最新です。",
