  "fed {count} declarations": "{count} 件の申告に反映",
  "last updated {days}d ago": "最終更新 {days} 日前",
  "What this is built from": "この集計の元データ",
  "{datasets} submitted supplier datasets across {declarations} declarations, costed with the same engine the declaration workspace uses — the Annex II direct-only rule for steel and aluminium, default-value markups where a supplier reported on defaults, and any carbon price already paid deducted. Nothing here is a filed figure.": "{declarations} 件の申告にわたる、提出済みのサプライヤーデータセット {datasets} 件。申告ワークスペースと同じエンジンでコストを算出しています。鉄鋼およびアルミニウムには附属書IIの直接排出のみのルールを適用し、サプライヤーがデフォルト値で報告した場合はデフォルト値の割増を適用し、支払い済みの炭素価格は差し引いています。ここに表示される数値は届出済みの数値ではありません。",
