  "Go to {step}": "{step} へ移動",
  "Every supplier submission must be approved before the report can be generated — the package only ever contains verified data.": "レポートを生成する前に、すべてのサプライヤー提出内容を承認する必要があります。パッケージには検証済みのデータだけが含まれます。",
  "Generate the report first — sign-off is a confirmation of the exact package that will be sent.": "先にレポートを生成してください。承認は、送信される正確なパッケージを確認する手続きです。",
  "Internal sign-off must be complete before anything is dispatched — every requested confirmation has to land first.": "何かを送信する前に、社内承認を完了させる必要があります。依頼されたすべての確認が先に完了している必要があります。",
  "Awaiting review": "レビュー待ち",
  "Changes requested": "変更依頼中",
  "Approved": "承認済み",
  "Supplier submissions": "サプライヤー提出物",
  "Each supplier filled their own Smart Link, the AI checked it, they e-signed and submitted. Open a submission to read the data, loop in your internal reviewers, then approve it or request a revision.": "各サプライヤーは自身の Smart Link に入力し、AI がチェックし、電子署名のうえ提出しています。提出内容を開いてデータを確認し、社内レビュー担当者に共有したうえで、承認するか修正を依頼してください。",
  "{count} of these products are produced by you — no link goes out for them; fill them in here and they run through the same checks.": "これらの製品のうち {count} 件は貴社が生産しています。これらについてはリンクは送信されません。ここで入力すると、同じチェックを経て処理されます。",
  "Reminder sent": "リマインダーを送信しました",
  "{name} nudged by email to complete their Smart Link.": "{name} にメールで Smart Link の入力を促しました。",
  "from record": "記録から",
  "Pulled from this company's own supplier record — they answered these goods on another declaration": "この会社のサプライヤー記録から取得しました。別の申告でこれらの品目に回答済みです",
  "score": "スコア",
  "reminded {ago}": "{ago} にリマインド",
