  "signed by {name} ({role})": "{name}（{role}）が署名",
  "our own installation": "自社設備",
  "CBAM-critical: this supplier carries a major share of the declaration's embedded emissions — the package can't be filed without them.": "CBAM 重要：このサプライヤーは申告の埋め込み排出量の大部分を占めています。このサプライヤーのデータがなければ、パッケージは届出できません。",
  "Your organisation": "貴社の組織",
