  "not started (critical)": "未着手（重要）",
  "No Smart Link goes out for these — {supplier} is you. Report the embedded emissions of your own installation the same way an external supplier would, and the declaration treats it identically: same {regulation} checklist, same AI check, same verification trail.": "これらにはスマートリンクは送信されません。{supplier}は貴社です。外部サプライヤーと同様に、自社施設の含有排出量を報告してください。申告では同様に扱われ、同じ{regulation}チェックリスト、同じAIチェック、同じ検証の記録が適用されます。",
  "You’re {supplier}. To keep shipping {origin} {sector} into the {destination}, {exporter} has to report the embedded emissions of the goods they buy from you — under {regulation}. This takes about 10 minutes, it’s free, and you don’t need an account.": "貴社は{supplier}です。{origin}の{sector}製品を{destination}へ引き続き出荷するには、{exporter}が貴社から購入する製品の含有排出量を、{regulation}に基づいて報告する必要があります。所要時間は約10分で、無料です。アカウントは不要です。",
  "Your figures are checked automatically before you submit and land in your own supplier record, so the next declaration starts pre-filled instead of blank. Colleagues can be assigned the sections that belong to their department.": "数値は送信前に自動でチェックされ、貴社のサプライヤー記録に保存されます。そのため、次回の申告は空欄ではなく事前入力された状態から始まります。部門ごとのセクションを同僚に割り当てることもできます。",
  "Your figures are checked automatically before you submit, encrypted, and shared only with {exporter} for this declaration. You can invite colleagues to fill the parts that belong to their department.": "数値は送信前に自動でチェックされ、暗号化されて、この申告のために{exporter}とだけ共有されます。部門ごとの担当部分を、同僚を招待して入力させることもできます。",
  "Reporting as": "報告者",
