  "Please report at installation level using actual data where you have it. If you only have default factors, mark the method as “default”. Reach out if anything is unclear — we'd rather help than receive a guess.": "実データがある場合は、施設単位で実データを用いて報告してください。デフォルト係数しかない場合は、方法を「デフォルト」と表示してください。不明な点があればご連絡ください。推測の値を受け取るより、支援させていただきます。",
  "Who produced the goods and where.": "製品を製造した者と、その場所です。",
  "Route and quantity per good.": "製品ごとの工程と数量です。",
  "Direct & indirect emissions per tonne.": "トン当たりの直接・間接排出量です。",
