  "Emissions against the EU default": "EUデフォルト値との比較による排出量",
  "What your goods carry each month, and what the EU would assume for the same tonnes": "貴社の製品が毎月含む排出量と、同じ重量についてEUが想定する排出量です",
  "Open Carbon & Cost": "炭素とコストを開く",
  "charged": "課金額",
  "Your data": "貴社のデータ",
  "Embedded emissions by month against the EU default": "EUデフォルト値と比較した月別の含有排出量",
