  "{n} item(s) are overdue.": "{n}件の項目が期限超過です。",
  "Your own data saves {amount} against the EU default.": "貴社のデータにより、EUデフォルト値と比べて{amount}削減されています。",
  "Nothing is late and nothing worries me. A good time to look ahead.": "遅延はなく、懸念もありません。先を見据える良い機会です。",
