  "What stands out today": "本日の注目点",
  "Ask about your data…": "データについて質問…",
  "How far each report has got": "各レポートの進捗状況",
  "By installation and reporting year; the tick is where the year should be by now": "施設と報告年度別。チェックマークは、現時点で年間データがあるべき位置を示します",
  "Open Verification": "検証を開く",
  "No report yet.": "レポートはまだありません。",
  "Package ready to send": "送信可能なパッケージ",
  "{n} blocked, {m} items holding the package": "停止中 {n}件、パッケージを保留させている項目 {m}件",
  "{m} items holding the package": "パッケージを保留させている項目 {m}件",
  "Compliance status": "コンプライアンス状況",
  "Each part of the filing, across every product report": "すべての製品レポートにわたる、申告の各部分",
  "{n} of {m} reports complete": "{m}件中{n}件のレポートが完了",
  "Late or about to be, most overdue first": "遅延中、または遅延直前のもの。期限超過が大きい順",
  "Dates that matter": "重要な日付",
  "From the CBAM regulation as amended in 2025": "2025年に改正されたCBAM規則による",
  "in {n} days": "あと{n}日",
  "Where it worries us": "懸念のある箇所",
  "Open Supply Chain": "サプライチェーンを開く",
  "Parties in the supply chain by state": "状態別のサプライチェーン関係者",
  "Nothing worries us in the chain right now.": "現時点でチェーンに懸念はありません。",
