  "{n}m ago": "{n}分前",
  "{n}h ago": "{n}時間前",
  "{n}d ago": "{n}日前",
  "The last things that changed across your reports": "レポート全体で最近変更された内容",
  "Entries per page": "1ページあたりの件数",
  "entries per page": "1ページあたりの件数",
  "Pick a prompt below, or just tell me what you need.": "下のプロンプトから選ぶか、必要な内容をそのまま入力してください。",
  "Your numbers": "貴社の数値",
  "Where you stand, what is late, what is open": "現在の状況、遅延、未対応事項",
  "Need more options? Let me know.": "他の選択肢が必要ですか？お知らせください。",
  "Ask again": "もう一度尋ねる",
  "Cera can make mistakes. Check important information.": "Ceraは誤る場合があります。重要な情報は確認してください。",
  "What the cost rests on": "コストの根拠",
  "Change a price here and every page of the portal uses it": "ここで価格を変更すると、ポータルのすべてのページに反映されます",
  "CBAM certificates start with 2026 imports.": "CBAM証明書は2026年の輸入分から始まります。",
  "Free allocation left": "残りの無償割当",
  "Default mark-up": "デフォルトの上乗せ率",
  "Certificate price {year}": "{year}年の証明書価格",
  "Exchange rate": "為替レート",
  "Used to show every euro figure in baht, yuan and rupees.": "すべてのユーロ建ての数値を、バーツ、元、ルピーで表示するために使用します。",
  "The cross-sectoral correction factor is taken as 1: the Commission has not published it in the rules this was built from.": "分野横断補正係数は1として扱われます。欧州委員会は、本機能の基となった規則でこれを公表していません。",
  "A bought-in precursor's own free allocation is not netted off, so a complex good's cost is never shown lower than it is.": "購入した前駆体自体の無償割当は相殺されません。そのため、複合製品のコストが実際より低く表示されることはありません。",
  "{n} product(s) have no EU volume entered, so all the tonnes made are assumed shipped to the EU.": "{n}件の製品にEU向けの数量が入力されていないため、製造したすべての重量がEUに出荷されたものと想定しています。",
  "A carbon price paid at home is recorded for {n} product(s). It is shown as claimed and never subtracted.": "国内で支払われた炭素価格が{n}件の製品について記録されています。申請済みとして表示され、差し引かれることはありません。",
  "Fuel burned and process emissions": "燃料燃焼と工程排出",
  "of the total": "合計に占める割合",
  "Electricity: reported, not charged for steel and aluminium": "電力：報告対象。鉄鋼・アルミニウムについては課金されません",
  "Electricity: counts toward the certificate bill": "電力：証明書の請求額に算入",
  "Electricity: charged for some goods, not for others": "電力：一部の製品については課金、その他は対象外",
  "What the bought-in inputs already carry": "購入した投入物が既に含んでいる排出量",
  "Nothing bought in carries emissions here": "ここでは、購入した投入物に排出量は含まれません",
  "on a default value": "デフォルト値による",
  "Cost with your data": "自社データによるコスト",
  "Cost on the EU default": "EUデフォルト値によるコスト",
  "What an importer pays when nobody gives them a real figure": "実際の数値が提供されない場合に輸入者が支払う額",
  "Total embedded": "含有排出量の合計",
  "Emissions month by month": "月別の排出量",
  "On the tonnes made, against the EU default for the same tonnes": "製造した重量について、同じ重量のEUデフォルト値と比較",
  "The dark line is what the certificate bill is raised on. Electricity counts only for goods where the rules charge it.": "濃い線は、証明書の請求額の算出基準です。電力は、規則上課金対象となる製品についてのみ算入されます。",
  "The dark line is what the certificate bill is raised on: direct plus precursors, and electricity only where the rules charge it.": "濃い線は、証明書の請求額の算出基準です：直接排出と前駆体の排出、および規則上課金対象となる場合にのみ電力を算入します。",
  "Precursors are declared once for the year, so they move with production, not with the month.": "前駆体は年に一度申告されるため、月ではなく生産量に応じて変動します。",
  "The shaded months are carried forward at this year's rate, not measured.": "網掛けの月は計測値ではなく、今年のペースを引き継いで算出しています。",
  "What your data saves": "自社データによる削減効果",
  "{pct} less than the EU default": "EUデフォルト値より{pct}少ない",
  "Not enough to compare yet": "比較するにはまだデータが不足しています",
  "With your data": "自社データを使用",
  "On the EU default": "EUデフォルト値を使用",
  "Tonnes the bill is on": "請求額の算出対象となる重量",
  "Carbon price paid at home, if accepted": "国内で支払った炭素価格（受理された場合）",
  "Shown as claimed and never subtracted: the EU has not settled whether it accepts it.": "申請済みとして表示され、差し引かれることはありません。EUがこれを受理するかは未確定です。",
  "Fuel and process": "燃料と工程",
  "Bought-in inputs": "購入した投入物",
  "What it is made of": "構成内容",
  "Share of the total embedded emissions": "含有排出量の合計に占める割合",
  "Direct, indirect and precursor emissions as a share of the total": "直接排出、間接排出、前駆体排出の合計に占める割合",
  "{pct} of the precursor emissions rest on a default value, which carries a mark-up. A verified figure from that supplier usually lowers it.": "前駆体排出量の{pct}はデフォルト値によるもので、上乗せが含まれます。そのサプライヤーからの検証済みの数値があれば、通常は下がります。",
  "Every precursor figure comes from a supplier, none from a default value.": "すべての前駆体の数値はサプライヤーから提供されており、デフォルト値によるものはありません。",
  "per tonne": "トン当たり",
  "per piece": "個当たり",
  "Cost per unit": "単位当たりのコスト",
  "What the energy and the carbon cost, against what the good sells for": "製品の販売価格に対する、エネルギーと炭素のコスト",
