  "e.g. scrap-fed EAF steelmaking from scrap receipt through continuous casting and hot rolling; the on-site fabrication shop serving the domestic market is outside the boundary": "例：スクラップ受入から連続鋳造、熱間圧延までのスクラップ原料EAF製鋼。国内市場向けの構内加工工場は境界の外です",
  "e.g. every figure is entered by production and checked by ESG before sign-off": "例：すべての数値は生産部門が入力し、承認前にESG部門が確認",
  "Look at the share of embedded emissions on default values (summary report, item 4(b)). A default is a published figure with the year’s mark-up added, not something you measured.": "デフォルト値による含有排出量の割合を確認してください（概要レポート、項目4(b)）。デフォルト値は、その年の上乗せを加えて公表された数値であり、貴社が計測したものではありません。",
