  "First-year verification includes a site visit, so line up your verifier early and keep the months coming in.": "初年度の検証には現地訪問が含まれるため、検証者を早めに手配し、月次データを継続して入力してください。",
  "The dashboard shows how far each report has got, and which ones are holding the package up.": "ダッシュボードには、各レポートの進捗と、パッケージを保留させているレポートが表示されます。",
  "Your free trial has ended": "無料トライアルは終了しました",
  "Everything you built is still here and still readable, but nothing can be changed, sent or downloaded until you choose a plan.": "作成したものはすべて残っており、閲覧は可能です。ただし、プランを選択するまで、変更、送信、ダウンロードはできません。",
