  "If that was you, there is nothing to do. If it was not, change your password now and sign out the other sessions.": "ご自身による操作であれば、対応は不要です。心当たりがない場合は、今すぐパスワードを変更し、他のセッションからサインアウトしてください。",
  "Your password was changed": "パスワードが変更されました",
