  "Ask Cera about this": "このことをCeraに質問",
  "Certrace now speaks 中文 and हिन्दी": "Certraceが中文とहिन्दीに対応しました",
  "The whole portal, the smart links your suppliers open, and Cera now work in English, ไทย, 中文 and हिन्दी.": "ポータル全体、サプライヤーが開くスマートリンク、Ceraが英語、ไทย、中文、हिन्दीで利用できるようになりました。",
  "Change the language from the menu under your name. Cera answers in the language you write to her in.": "名前の下のメニューから言語を変更できます。Ceraは、入力した言語で回答します。",
  "Carbon & Cost and Supply Chain were redesigned": "炭素とコストおよびサプライチェーンを再設計しました",
  "Carbon & Cost now compares your sites, years and products in baht, euro, yuan or rupee, with the cost on your own figures set against the EU default.": "炭素とコストでは、貴社の拠点、年度、製品を、バーツ、ユーロ、元、ルピーで比較できるようになりました。自社データによるコストをEUデフォルト値と並べて表示します。",
  "Supply Chain scores every supplier and precursor on how reliably the data arrives, and says where it worries us.": "サプライチェーンでは、すべてのサプライヤーと前駆体について、データの届き方の信頼性を評価し、懸念のある箇所を示します。",
  "Notifications — {n} unread": "通知 — 未読 {n}件",
  "Sample notifications — your own data is not touched.": "サンプルの通知です。貴社のデータは変更されません。",
