  "This is the rules as Certrace has them, not a live feed. Check the official text before you rely on it.": "これはCertraceが保持している規則の内容であり、リアルタイムの情報ではありません。依拠する前に、公式の本文を確認してください。",
  "Open Coverage": "Coverageを開く",
  "Unread": "未読",
  "Account": "アカウント",
  "What needs you, what has just happened, and what Certrace has to tell you — drawn from the same figures as the dashboard.": "貴社の対応が必要な事項、直近の出来事、Certraceからのお知らせです。ダッシュボードと同じ数値に基づいています。",
  "Sample notifications.": "サンプルの通知です。",
  "These come from the made-up estate on the dashboard. Your own data is not touched.": "これらはダッシュボード上の架空の拠点一覧から生成されています。貴社のデータは変更されません。",
  "Needs action": "対応が必要",
  "Happened": "発生済み",
  "Messages": "メッセージ",
  "A notice appears when a month runs late, a supplier answers, a package is ready, or Certrace has something to say.": "月次データが遅延した場合、サプライヤーが回答した場合、パッケージが準備できた場合、またはCertraceからお知らせがある場合に通知が表示されます。",
  "CBAM news": "CBAMニュース",
  "Rule changes, new certificate prices and the dates that matter — as Certrace has them.": "規則の変更、新しい証明書価格、重要な日付です。Certraceが保持している内容に基づきます。",
  "Your trial, the limits of your plan and anything that needs your attention on it.": "貴社のトライアル、プランの上限、および注意が必要な事項です。",
  "Thailand's excise on oil products, which carries a carbon component of THB 200/tCO₂e — Excise Department notice in the Government Gazette of 22 April 2025, unchanged at 26 October 2026": "石油製品に対するタイの物品税は、炭素部分として1tCO₂eあたり200THBを含みます。2025年4月22日付官報の物品税局通知。2026年10月26日時点で変更なし",
  "Monthly schedule": "月次スケジュール",
  "The day of the month each month's data is due.": "各月のデータの提出期限となる日です。",
  "The report": "レポート",
  "Brought across as a draft you can edit. A finished version is never copied.": "編集可能な下書きとして引き継がれます。完成版がコピーされることはありません。",
  "Boundary and processes": "境界と工程",
  "The boundary description, the processes inside it and what is left out, with the ground for each.": "境界の説明、境界内の工程、除外されたものと、それぞれの根拠です。",
  "Fuels and electricity": "燃料と電力",
  "The fuels burned, the electricity supply and the meter it is read from.": "燃焼させた燃料、電力の供給、読み取りに使用するメーターです。",
  "Measuring instruments": "計測機器",
  "The instrument and the reading frequency for each fuel and for electricity.": "各燃料および電力の計測機器と読み取り頻度です。",
  "The estimates standing in for missing readings. They describe last year, so they start new unless you choose otherwise.": "欠損している読み取り値の代わりに用いる推定値です。前年度を対象とするため、別途選択しない限り新規として開始します。",
  "Who reviews the data, and how often.": "データを確認する担当者と、その頻度です。",
  "The drawing of the installation and what it shows.": "施設の図面と、その表示内容です。",
  "Steel: the reducing agent and the mill. Aluminium: the way perfluorocarbons are counted.": "鉄鋼：還元剤と圧延工場。アルミニウム：パーフルオロカーボンの算定方法です。",
  "Sampling plan": "サンプリング計画",
  "How the calculation factors are determined.": "算定係数の決定方法です。",
  "Control system": "管理体制",
  "The controls that keep the data right.": "データの正確性を保つための管理です。",
  "Who supplies what, in the same tree: names, countries, CN codes, routes and contacts. Not their figures, reports or links — those are asked again.": "同じツリー内での、供給者と供給内容：名称、国、CNコード、工程、連絡先です。数値、レポート、リンクは含みません。これらは改めて依頼されます。",
  "The instrument, the amount per tonne, the law it is charged under and who certifies it. The receipt and any rebate are left behind.": "機器、トン当たりの金額、適用される法令、および証明者です。領収書と還付は引き継がれません。",
  "Who makes it": "製造者",
  "The supplier, or your own site.": "サプライヤー、または貴社の拠点です。",
  "Monthly figures": "月次の数値",
