  "{n} months are not submitted, so the annual figure is **incomplete, not smaller**. Every per-tonne figure above divides by a denominator that is missing those months, which overstates them.": "{n}か月分が送信されていないため、年間の数値は**小さくなるのではなく、不完全**です。上記のトン当たりの数値はすべて、それらの月が欠けた分母で除算されているため、過大に表示されます。",
